result:
.label-wrapper
  .list
    display: flex;
    flex-wrap: wrap;
    .label-pro{
      border: 1px solid #FFFFFF;
      padding: 2px;
      border-radius: 4px;
      margin: 0 8px 10px 0;
      cursor: pointer;
    }
    .active-label{
      border: 1px solid #2d8cf0;
    }
    .label-item {
      padding: 2px 8px;
      background: #EEEEEE;
      color: #333333;
      border-radius: 2px;
      font-size: 12px;
    }
    .sanjiao{
      position: absolute;
      right: 0;
      bottom: 0;
      width: 20px;
      height: 20px;
      background: #2d8cf0;
      clip-path: polygon(100% 100%, 100% 0, 0 100%);
      color: #fff;
      text-align: right;
      .iconfont{
        font-size: 10px;
      }
    }
  .footer
    display flex
    justify-content flex-end
    margin-top 40px

    button
      margin-left 10px

.btn
  width 60px
  height 24px

.title
  font-size 13px

.list-box
  overflow-y auto
  overflow-x hidden
  max-height 340px

  &::-webkit-scrollbar {
    width: 0;
  }

.img-tag {
  height: 22px;
  border-radius: 2px;
}
